export const accountantMininterFullMock3: TestDef = {
  country: 'RW', category: 'accounting-finance', profession: ACCOUNTANT, jobDeadlineAt: DEADLINE,
  slug: 'accountant-mininter-full-mock-exam-3',
  title: 'Accountant (MININTER) — Mock Exam 3',
  summary: 'A full-length practice exam for ministry accountant recruitment, covering accounting fundamentals, budget monitoring, reconciliation and reporting, psychometric reasoning, and a multi-line budget execution case.',
  free: false, difficulty: 'STANDARD', minutes: 120,
  sections: [{ name: AS }, { name: BIM }, { name: RR }, { name: PSY }, { name: 'Case study: Musanze District Roads Unit', label: 'Case-based, 8 linked questions' }],
  cases: [{
    key: 'musanze-roads',
    title: 'Musanze District Roads Unit, fourth quarter of FY2025/26',
    passage: ['The Musanze District Roads Unit is closing out its fourth-quarter 2025/26 budget execution report and checking a payroll calculation for its site supervisor.'],
    tables: [
      { caption: 'Budget execution, Q4 2025/26 (RWF)', rows: [
        { label: 'Road grading and gravel — approved', value: '45,000,000' },
        { label: 'Road grading and gravel — actual', value: '52,300,000' },
        { label: 'Culvert repairs — approved', value: '18,000,000' },
        { label: 'Culvert repairs — actual', value: '11,400,000' },
        { label: 'Office running costs — approved', value: '6,000,000' },
        { label: 'Office running costs — actual', value: '6,050,000' },
      ] },
      { caption: 'Site supervisor payroll (RWF)', rows: [
        { label: 'Gross monthly salary', value: '380,000' },
        { label: 'PAYE withheld', value: '38,000' },
        { label: 'Pension contribution withheld', value: '30,400' },
      ] },
    ],
    notes: [
      'The overspend on road grading and gravel was mainly caused by a steep mid-year rise in gravel transport costs.',
      'The underspend on culvert repairs was caused by a contractor delay; the remaining work will need a new purchase order in 2026/27, not an automatic carry-over of this year’s unspent budget.',
    ],
  }],
  questions: [
    { section: AS, topic: AS, stem: 'What is the main difference between capital expenditure and revenue expenditure?', options: ['There is no difference', 'Capital expenditure creates or improves a long-term asset; revenue expenditure covers day-to-day running costs', 'Revenue expenditure is always larger', 'Capital expenditure is never budgeted'], correct: 1, explanation: 'Capital expenditure buys or improves assets that provide benefits over several years, while revenue expenditure covers costs consumed within the current period.' },
    { section: AS, topic: AS, stem: 'Rent paid in advance for the next financial year should be shown in the accounts as…', options: ['A liability', 'An expense of the current year', 'A prepayment (current asset)', 'Equity'], correct: 2, explanation: 'A prepayment is a payment made for a benefit not yet received; it is recorded as a current asset until the period it relates to arrives.' },
    { section: AS, topic: AS, stem: 'An expense has been incurred but not yet paid or recorded at year end. How should it be treated under accrual accounting?', options: ['Ignored until it is paid', 'Recognised as an accrued expense (a current liability) in the period it relates to', 'Recorded as income', 'Deferred to two years later'], correct: 1, explanation: 'Under accrual accounting, an expense that has been incurred but not yet paid is recognised as a liability (an accrual) in the period it relates to.' },
    { section: AS, topic: AS, stem: 'What is the purpose of a provision for doubtful debts?', options: ['To increase reported profit', 'To recognise, in advance, the likelihood that some debts owed to the institution will not be collected', 'To write off all debts automatically', 'To replace the need for credit control'], correct: 1, explanation: 'A provision for doubtful debts anticipates that some receivables may not be collected, so the accounts are not overstated with amounts unlikely to be received.' },
    { section: AS, topic: AS, stem: 'What is a suspense account used for?', options: ['Recording confirmed fraud cases', 'Temporarily holding an unidentified difference or unclear item until it can be investigated and correctly classified', 'Paying suppliers who have no bank account', 'Replacing the cash book'], correct: 1, explanation: 'A suspense account is a temporary holding place for amounts that cannot yet be correctly classified, used until the issue is investigated and resolved.' },
    { section: AS, topic: AS, stem: 'What is the main purpose of a control account, such as a debtors or creditors control account?', options: ['To replace subsidiary ledgers entirely', 'To provide a summary total that should agree with the sum of the individual balances in the subsidiary ledger, helping detect errors', 'To record cash transactions only', 'To calculate depreciation'], correct: 1, explanation: 'A control account totals a category of transactions and should reconcile with its subsidiary ledger, helping to catch recording errors early.' },
    { section: AS, topic: AS, stem: 'What is the main purpose of an imprest (petty cash) system?', options: ['To avoid ever recording small transactions', 'To control small, routine cash payments by replenishing a fixed float only up to supported, recorded spending', 'To pay large supplier invoices', 'To replace the main bank account'], correct: 1, explanation: 'An imprest system keeps a fixed float for small expenses, topped up only to the amount of properly recorded and supported spending, which limits the cash at risk and keeps small payments auditable.' },
    { section: AS, topic: AS, stem: 'What is the main purpose of a fixed asset register?', options: ['To record staff attendance', 'To track the existence, location, condition and value of assets owned by the institution', 'To replace the annual budget', 'To calculate statutory tax deductions'], correct: 1, explanation: 'A fixed asset register records details such as location, condition and value for each asset, supporting safeguarding, depreciation calculations and physical verification.' },
    { section: AS, topic: AS, stem: 'How does internal audit differ from day-to-day internal control and supervisory “internal checks” carried out by staff?', options: ['They are exactly the same thing', 'Internal audit is an independent, periodic review of how well controls and checks are working, while internal control and internal checks are built into daily operations', 'Internal audit replaces the need for any daily controls', 'Internal checks are performed only by external parties'], correct: 1, explanation: 'Internal controls and checks are routine safeguards built into daily work; internal audit independently and periodically evaluates whether those controls and checks are actually working well.' },
    { section: AS, topic: AS, stem: 'What is the key difference between an error and fraud in financial records?', options: ['There is no difference', 'An error is unintentional; fraud involves an intentional act to deceive or gain improperly', 'Fraud is always smaller in value than an error', 'Errors only occur in manual systems'], correct: 1, explanation: 'An error is an unintentional mistake, while fraud is a deliberate act intended to deceive or obtain an improper benefit — the distinction matters for how each should be investigated and addressed.' },

    { section: BIM, topic: BIM, stem: 'What does “budget absorption” refer to, and why does persistently low absorption raise concern?', options: ['It has no real meaning', 'It is the rate at which approved budget is actually spent on its intended purpose; low absorption can signal planning, procurement or implementation problems', 'It only measures how much cash is physically in the safe', 'It refers to tax absorption by citizens'], correct: 1, explanation: 'Low absorption means approved funds are not being used as planned, which often points to delays in procurement, implementation capacity, or unrealistic planning.' },
    { section: BIM, topic: BIM, stem: 'Why should budget execution be monitored against the institution’s medium-term (MTEF) priorities, not only the current year’s figures?', options: ['It has no added value', 'It helps confirm that spending stays aligned with longer-term goals and genuinely supports value for money over time', 'MTEF priorities change too often to matter', 'Only donors care about medium-term alignment'], correct: 1, explanation: 'Checking execution against medium-term priorities, not just annual figures, helps ensure spending keeps delivering on longer-term objectives rather than drifting from them.' },
    { section: BIM, topic: BIM, stem: 'A budget line is close to being fully spent well before the quarter ends. What should the accountant do?', options: ['Say nothing until the line is fully exhausted', 'Flag the near-exhaustion to management promptly, so a decision can be made before an overspend or a funding gap occurs', 'Stop recording further transactions against that line', 'Automatically approve an unbudgeted virement without authority'], correct: 1, explanation: 'Early warning gives management time to decide on a remedy, such as an authorised virement, before the line is fully exhausted or overspent.' },
    { section: BIM, topic: BIM, stem: 'Why do procurement delays often explain an underspend on a capital or maintenance budget line?', options: ['Procurement delays never affect spending', 'If goods, works or services have not yet been delivered, the related payments have not yet fallen due, even though budget was approved', 'Underspends are always due to poor budgeting, never procurement', 'Procurement delays only affect revenue lines'], correct: 1, explanation: 'Spending generally follows delivery; if procurement is delayed, the corresponding payments are delayed too, producing an apparent underspend against the approved budget.' },
    { section: BIM, topic: BIM, stem: 'At year end, a budget line still has an unspent balance for an activity that did not happen as planned. What is generally true about carrying that balance into the next year?', options: ['It automatically carries forward with no further process', 'It generally cannot simply roll over automatically; using it in the next year normally needs a fresh budget allocation or specific approval', 'It must always be returned to the supplier', 'It is deducted from staff salaries'], correct: 1, explanation: 'Public budgets are generally approved on an annual basis, so an unspent balance cannot simply be assumed to carry over; continuing the activity usually needs a new allocation or approval in the following year.' },
    { section: BIM, topic: BIM, stem: 'When analysing why actual costs differ from budget on a contracted activity, why is it useful to think separately about “price” effects and “quantity” effects?', options: ['It is never useful to separate them', 'Costs can rise because unit prices increased, because more was bought or done than planned, or both — separating the two shows what actually drove the variance', 'Price and quantity can never both change at once', 'Only quantity effects matter in the public sector'], correct: 1, explanation: 'A variance can come from paying a different price per unit, from a different quantity of work or goods than planned, or a mix of both; separating these helps explain the variance accurately.' },
    { section: BIM, topic: BIM, stem: 'How does timely bank and cash reconciliation support more accurate cash-flow forecasting?', options: ['It has no connection to forecasting', 'It confirms the true, current cash position, which is the correct starting point for projecting future receipts and payments', 'Reconciliation and forecasting use completely unrelated figures', 'Forecasting only needs the approved budget, never actual cash data'], correct: 1, explanation: 'An accurate, reconciled cash position is the right starting point for a forecast; relying on an unreconciled or outdated balance can distort projections.' },
    { section: BIM, topic: BIM, stem: 'Why does linking the payroll system with IFMIS reduce payment risk?', options: ['It increases manual handling of payroll data', 'It reduces manual re-entry of salary data into separate payment processes, lowering the risk of errors or unauthorised changes', 'It has no effect on payment accuracy', 'It removes the need for any payroll controls at all'], correct: 1, explanation: 'Interfacing payroll with IFMIS avoids re-keying salary information into a separate payment process, which reduces the chance of transcription errors or unauthorised tampering.' },
    { section: BIM, topic: BIM, stem: 'Why is a multi-year perspective, such as the MTEF, particularly useful for recurrent, multi-year contractual commitments?', options: ['Multi-year commitments are irrelevant to budgeting', 'It helps ensure the institution plans and reserves resources across future years for obligations that extend beyond the current budget year', 'Multi-year contracts are automatically funded regardless of future budgets', 'The MTEF only covers one year at a time'], correct: 1, explanation: 'Commitments that span several years need resources planned for in each of those years; a medium-term framework helps ensure future-year obligations are not overlooked.' },
    { section: BIM, topic: BIM, stem: 'When preparing MTEF estimates, why is it poor practice to simply inflate last year’s figures by a flat percentage rather than basing estimates on realistic cost drivers?', options: ['It is always the most accurate approach', 'A flat inflation ignores real changes in needs, prices or activity levels, and can over- or under-state what is actually required', 'Cost drivers never change from year to year', 'MTEF estimates are not meant to be realistic'], correct: 1, explanation: 'Simply scaling last year’s number does not reflect genuine changes in activity, prices or needs, and can produce estimates that are badly out of line with what will actually be required.' },

    { section: RR, topic: RR, stem: 'Why should an institution regularly reconcile its debtors and creditors subsidiary ledgers against their control accounts?', options: ['It is an unnecessary duplication of work', 'To catch recording errors or omissions early, before they accumulate into larger discrepancies', 'Control accounts never need to be reconciled', 'Only external auditors are allowed to perform this reconciliation'], correct: 1, explanation: 'Regular reconciliation between subsidiary ledgers and their control totals helps identify and correct errors promptly, before they build up into significant, harder-to-trace discrepancies.' },
    { section: RR, topic: RR, stem: 'Why does requiring two independent people to approve a high-value payment (a “four eyes” principle) help manage risk?', options: ['It only slows down payments with no real benefit', 'It reduces the chance that a single person’s error or dishonesty goes unchecked for large, high-impact transactions', 'It is required only for low-value transactions', 'It removes the need for supporting documents'], correct: 1, explanation: 'Dual approval for high-value payments means a mistake or improper transaction is less likely to pass through unnoticed, since a second independent reviewer must also agree.' },
    { section: RR, topic: RR, stem: 'What is a key risk of not maintaining an up-to-date fixed asset register?', options: ['There is no real risk', 'Assets could be lost, misused or misappropriated without being noticed, and depreciation or disposal decisions could be based on inaccurate information', 'It only affects staff morale', 'It prevents staff from taking annual leave'], correct: 1, explanation: 'Without accurate asset records, it becomes harder to detect missing or misused assets, and financial decisions about depreciation or disposal rest on unreliable information.' },
    { section: RR, topic: RR, stem: 'In a monthly report, what is the difference between flagging a “compliance issue” and flagging a “financial misstatement”?', options: ['They always mean exactly the same thing', 'A compliance issue is a departure from a rule or procedure; a financial misstatement is an error or omission in the reported figures themselves, though the two can be related', 'Compliance issues can never affect figures', 'Misstatements are always deliberate'], correct: 1, explanation: 'A compliance issue concerns not following a required rule or process, while a misstatement concerns the accuracy of the figures reported; one can lead to the other, but they are not identical concepts.' },
    { section: RR, topic: RR, stem: 'Why should an accountant avoid waiting until year end to investigate unexplained reconciling items?', options: ['Unexplained items resolve themselves naturally over time', 'Problems become harder to trace and correct the longer they are left unresolved', 'Reconciling items are never a real concern', 'Investigating them only matters for external auditors'], correct: 1, explanation: 'The longer an unexplained item sits unresolved, the more records and context can be lost, making it progressively harder to trace the root cause.' },
    { section: RR, topic: RR, stem: 'Cash book balance is RWF 11,300,000. Bank charges of RWF 140,000 appear on the statement but are not yet recorded in the cash book. What is the adjusted cash book balance?', options: ['RWF 11,440,000', 'RWF 11,160,000', 'RWF 11,300,000', 'RWF 140,000'], correct: 1, explanation: 'Adjusted balance = 11,300,000 − 140,000 = 11,160,000.' },
    { section: RR, topic: RR, stem: 'Bank statement balance is RWF 15,500,000. Unpresented cheques total RWF 3,100,000, and a deposit of RWF 600,000 has not yet been credited. What is the adjusted bank balance?', options: ['RWF 18,000,000', 'RWF 12,000,000', 'RWF 13,000,000', 'RWF 19,200,000'], correct: 2, explanation: 'Adjusted balance = 15,500,000 − 3,100,000 + 600,000 = 13,000,000.' },
    { section: RR, topic: RR, stem: 'Approved annual budget for a line is RWF 320,000,000; actual expenditure is RWF 299,200,000. What is the variance, and what type is it?', options: ['RWF 20,800,000 underspend', 'RWF 20,800,000 overspend', 'RWF 619,200,000 underspend', 'No variance'], correct: 0, explanation: 'Variance = 320,000,000 − 299,200,000 = 20,800,000. Since actual is below budget, this is an underspend.' },
    { section: RR, topic: RR, stem: 'Approved quarterly budget for a line is RWF 25,000,000; actual expenditure is RWF 31,750,000. What is the variance, and what type is it?', options: ['RWF 6,750,000 overspend', 'RWF 6,750,000 underspend', 'RWF 56,750,000 overspend', 'No variance'], correct: 0, explanation: 'Variance = 31,750,000 − 25,000,000 = 6,750,000. Since actual exceeds budget, this is an overspend.' },
    { section: RR, topic: RR, stem: 'Office furniture costs RWF 3,600,000, has no residual value and a useful life of 6 years. What is the annual straight-line depreciation charge?', options: ['RWF 600,000', 'RWF 360,000', 'RWF 3,000,000', 'RWF 60,000'], correct: 0, explanation: 'Depreciation = (3,600,000 − 0) ÷ 6 = 600,000 per year.' },
    { section: RR, topic: RR, stem: 'Total payroll cost for a quarter is RWF 40,000,000, of which RWF 6,000,000 is allowances. What percentage of payroll cost is allowances?', options: ['12%', '15%', '18%', '20%'], correct: 1, explanation: '6,000,000 ÷ 40,000,000 = 0.15, or 15%.' },

    { section: PSY, topic: PSY, stem: 'RWF 64,000,000 is split between two offices in the ratio 3:5. What is the smaller share?', options: ['RWF 16,000,000', 'RWF 20,000,000', 'RWF 24,000,000', 'RWF 40,000,000'], correct: 2, explanation: 'Total parts = 3+5 = 8. Each part = 64,000,000 ÷ 8 = 8,000,000. Smaller share = 3 × 8,000,000 = 24,000,000.' },
    { section: PSY, topic: PSY, stem: 'A review of 125 transactions flagged 25 for further checking. What percentage of transactions were flagged?', options: ['15%', '18%', '20%', '25%'], correct: 2, explanation: '25 ÷ 125 = 0.20, or 20%.' },
    { section: PSY, topic: PSY, stem: 'A debt of RWF 3,600,000 is to be repaid in 6 equal instalments. After 4 instalments have been paid, how much remains?', options: ['RWF 600,000', 'RWF 1,200,000', 'RWF 1,800,000', 'RWF 2,400,000'], correct: 1, explanation: 'Each instalment = 3,600,000 ÷ 6 = 600,000. Four paid = 2,400,000. Remaining = 3,600,000 − 2,400,000 = 1,200,000.' },
    { section: PSY, topic: PSY, stem: 'A budget line is cut from RWF 5,000,000 to RWF 4,250,000. What is the percentage cut?', options: ['10%', '15%', '20%', '25%'], correct: 1, explanation: '(5,000,000 − 4,250,000) ÷ 5,000,000 = 0.15, or 15%.' },
    { section: PSY, topic: PSY, stem: 'Five accounts hold RWF 800,000, RWF 1,100,000, an unknown amount, RWF 750,000 and RWF 900,000. Together they total RWF 5,000,000. What is the unknown amount?', options: ['RWF 1,250,000', 'RWF 1,350,000', 'RWF 1,450,000', 'RWF 1,550,000'], correct: 2, explanation: '5,000,000 − 800,000 − 1,100,000 − 750,000 − 900,000 = 1,450,000.' },
    { section: PSY, topic: PSY, stem: 'Rule: “All reconciled accounts show zero unexplained variance.” Account Y currently shows zero unexplained variance. Can we conclude Account Y has definitely been reconciled?', options: ['Yes, zero variance always means it was reconciled', 'No — an account could show zero variance by coincidence without having actually gone through reconciliation', 'Yes, but only for bank accounts', 'An account cannot show zero variance unless reconciled'], correct: 1, explanation: 'The rule tells us reconciled accounts show zero variance, not that only reconciled accounts can ever show zero variance — it could be coincidental or simply unchecked.' },
    { section: PSY, topic: PSY, stem: 'Rule: “No payment is released unless its budget check has passed.” Payment Z has been released. What can we conclude?', options: ['Nothing can be concluded', 'Its budget check must have passed, since passing the check is a necessary condition for release', 'The payment must be fraudulent', 'The rule does not apply to Payment Z'], correct: 1, explanation: 'Since the rule makes a passed budget check a requirement for release, the fact that Payment Z was released confirms its budget check passed — this is a valid inference, unlike assuming the reverse.' },
    { section: PSY, topic: PSY, stem: 'Policy requires legal review before any contract renewal is signed. Contract W was signed without that review. What does this indicate?', options: ['Nothing of concern, since the contract is already signed', 'A breach of policy that should be reported and investigated, regardless of whether anything turns out to be wrong with the contract itself', 'That legal review is optional for renewals', 'That the contract is automatically invalid everywhere'], correct: 1, explanation: 'Skipping a required step is a policy breach worth reporting and investigating on its own terms, whatever the eventual outcome regarding the contract’s content.' },
    { section: PSY, topic: PSY, stem: 'A senior colleague with no approval authority over a particular payment asks you to approve it slightly above your own authorised limit, “just this once.” What should you do?', options: ['Approve it as a favour, since they are senior', 'Decline, and refer the payment to someone with the correct authority and limit', 'Approve half the amount as a compromise', 'Ask the supplier to lower the amount temporarily'], correct: 1, explanation: 'Approval limits exist to ensure the right level of authority reviews a payment; a request to bypass them, however well-meant, should be declined and referred properly.' },
    { section: PSY, topic: PSY, stem: 'Year end is approaching and a budget line still holds significant unspent funds for an activity that has not yet happened. What is the best approach?', options: ['Rush unplanned spending before the deadline to “use up” the balance', 'Report the likely underspend and its reasons honestly, and follow the proper process for any carry-over or reallocation', 'Transfer the funds to a personal advance account for safekeeping', 'Hide the balance from the year-end report'], correct: 1, explanation: 'Honest reporting of an underspend, followed by the correct process for any reallocation, protects both transparency and the integrity of the budget — rushed, unplanned spending does not.' },
    { section: PSY, topic: PSY, stem: 'You find a minor transposition error in a report already sent to management, which does not change any key conclusions. What should you do?', options: ['Leave it, since it does not change key figures', 'Correct it and notify those who received the report, so an accurate version is on file', 'Wait for someone else to notice it', 'Resend the whole report without mentioning the correction'], correct: 1, explanation: 'Even a minor, immaterial error should be corrected and communicated, so the record on file is accurate and transparent — quietly leaving a known error uncorrected is poor practice.' },
    { section: PSY, topic: PSY, stem: 'Your supervisor is on leave and an urgent payment needs an approval they would normally give. What should you do?', options: ['Approve it yourself without the proper authority to avoid delay', 'Follow the institution’s defined delegation or backup-approval procedure', 'Delay the payment indefinitely until the supervisor returns', 'Ask the supplier to approve it instead'], correct: 1, explanation: 'Urgent approvals should go through the proper delegated backup authority, rather than being approved without authority or left stalled until the supervisor returns.' },

    { section: AS, topic: AS, stem: 'Which IPSAS qualitative characteristic is most directly supported by having information available in time to influence a decision?', options: ['Timeliness', 'Verifiability', 'Comparability', 'Understandability'], correct: 0, explanation: 'Timeliness means information is available to decision-makers in time to be capable of influencing their decisions; information that arrives too late loses much of its value.' },
    { section: AS, topic: AS, stem: 'What does "verifiability" mean as a qualitative characteristic of financial information?', options: ['Only the finance minister can check it', 'Different knowledgeable, independent observers could reach general consensus that the information faithfully represents what it claims to', 'It means the figures are rounded', 'It applies only to cash balances'], correct: 1, explanation: 'Verifiability means that knowledgeable, independent observers, checking the same evidence, could reach broad agreement that the information is a faithful representation.' },
    { section: AS, topic: AS, stem: 'A finance officer is asked to backdate a receipt to make end-of-quarter revenue figures look better. What should they do?', options: ['Comply, since it is only a timing change', 'Refuse, because backdating misstates the period revenue was actually received and distorts reported figures', 'Comply, but only if asked by a senior manager', 'Backdate it but keep a private note of the real date'], correct: 1, explanation: 'Backdating a receipt misstates the true period of a transaction and undermines the reliability of reported figures; it should be refused regardless of who requests it.' },
    { section: AS, topic: AS, stem: 'Why does an institution need a documented chart of accounts?', options: ['It has no functional purpose', 'It provides a consistent structure for classifying transactions, supporting accurate recording and comparable reporting', 'It replaces the need for an annual budget', 'It is only used by external auditors'], correct: 1, explanation: 'A chart of accounts gives a consistent classification structure for every transaction, which underpins accurate recording and comparable financial reporting over time.' },
    { section: AS, topic: AS, stem: 'A laptop costing RWF 1,400,000 has no residual value and a 4-year useful life. What is its net book value after 3 years of straight-line depreciation?', options: ['RWF 350,000', 'RWF 1,050,000', 'RWF 700,000', 'RWF 1,400,000'], correct: 0, explanation: 'Annual depreciation = 1,400,000 ÷ 4 = 350,000. After 3 years, accumulated depreciation = 1,050,000. Net book value = 1,400,000 − 1,050,000 = 350,000.' },
    { section: AS, topic: AS, stem: 'Why should accounting records distinguish clearly between restricted (earmarked) funds and unrestricted funds?', options: ['The distinction is meaningless in the public sector', 'So the institution can demonstrate that restricted funds were only used for their specified purpose, protecting compliance and donor trust', 'Restricted funds never need separate recording', 'Only private companies make this distinction'], correct: 1, explanation: 'Clearly tracking restricted funds separately lets an institution demonstrate compliance with the conditions attached to them, which matters for both internal control and donor/oversight confidence.' },
    { section: AS, topic: AS, stem: 'What is the purpose of a bank mandate (signatory list) for an institution’s accounts?', options: ['It has no real control purpose', 'It defines exactly who is authorised to sign for and release institutional funds, which the bank checks before acting', 'It only matters when opening a new account', 'It replaces the need for payment orders'], correct: 1, explanation: 'A bank mandate specifies the authorised signatories the bank will accept for transactions, forming a key external control over who can actually move institutional funds.' },
    { section: AS, topic: AS, stem: 'Why is prompt recording of transactions (rather than recording in batches much later) good practice?', options: ['It has no real benefit', 'It reduces the risk of errors, omissions or lost documentation, and keeps financial information current for decision-making', 'Prompt recording is only required for cash transactions', 'It is purely a matter of personal preference'], correct: 1, explanation: 'Recording transactions promptly reduces the chance that documents are lost or details forgotten, and keeps the accounting records current enough to support timely decisions.' },
    { section: AS, topic: AS, stem: 'An institution revalues a building upward based on an independent valuation. How should this generally be treated in the accounts?', options: ['Ignored completely', 'Recognised following the applicable IPSAS on property, with any gain typically taken to a revaluation surplus rather than straight to the surplus/deficit for the period', 'Recorded as ordinary annual income', 'Only disclosed verbally to the Minister'], correct: 1, explanation: 'Upward revaluations of property are generally recognised following the relevant standard, with the gain typically recorded in a revaluation surplus rather than treated as ordinary period income.' },
    { section: AS, topic: AS, stem: 'What is the main reason an institution should reconcile its fixed-asset register to the general ledger periodically?', options: ['It is not necessary once the register is created', 'To confirm the two records agree, since the register supports what is reported as property, plant and equipment in the financial statements', 'Reconciliation only applies to cash accounts', 'It replaces the need for physical verification entirely'], correct: 1, explanation: 'The fixed-asset register underpins the property, plant and equipment figures reported in the financial statements, so periodically confirming it agrees with the general ledger protects the accuracy of those figures.' },
    { section: AS, topic: AS, stem: 'Why might an institution write off a long-outstanding receivable that is judged unlikely to ever be collected?', options: ['Writing off receivables is never permitted', 'To ensure the financial statements do not overstate assets by carrying a balance unlikely to be realised, following proper authorisation', 'To avoid ever reporting on it again, even informally', 'Only the debtor can request a write-off'], correct: 1, explanation: 'Carrying a receivable that is genuinely unlikely to be collected would overstate assets; writing it off (with proper authorisation and continued record-keeping) keeps the financial statements realistic.' },
    { section: AS, topic: AS, stem: 'What role does the chief budget manager typically play in approving significant payment requests, beyond the accountant’s own check?', options: ['None — only the accountant’s check matters', 'They provide a separate, programme-level check that the spending is consistent with approved plans and priorities, adding a layer of accountability', 'They only sign documents without reviewing them', 'Their role is purely ceremonial'], correct: 1, explanation: 'The chief budget manager’s approval typically adds a programme-level perspective — confirming spending fits approved plans and priorities — alongside, not instead of, the accountant’s own financial checks.' },

    { section: BIM, topic: BIM, stem: 'Why is budget execution typically reported as a percentage of the annual approved budget, not just in absolute terms?', options: ['Percentages have no analytical advantage', 'A percentage lets readers judge execution pace relative to the full year regardless of the institution’s size, supporting comparison across time and units', 'Absolute figures are always more accurate', 'Percentages are only used for donor reports'], correct: 1, explanation: 'Expressing execution as a percentage of the approved annual budget allows comparison of pace and performance across different periods and differently sized institutions, which raw absolute figures alone do not easily support.' },
    { section: BIM, topic: BIM, stem: 'An institution’s capital budget execution rate is 40% by the third quarter (9 months) of the financial year. What might this most likely suggest?', options: ['Execution is exactly on the expected pace', 'Execution may be behind an even pace (which would be about 75% by this point), warranting investigation into delays', 'The institution has definitely overspent', 'Capital projects should never be monitored mid-year'], correct: 1, explanation: 'If three quarters (75%) of the year has passed but only 40% of the capital budget is executed, this suggests execution may be lagging an even pace and the causes of delay should be investigated.' },
    { section: BIM, topic: BIM, stem: 'A project budget of RWF 220,000,000 is split 45% for civil works, 35% for equipment and the remainder for consultancy. How much is allocated to consultancy?', options: ['RWF 22,000,000', 'RWF 44,000,000', 'RWF 33,000,000', 'RWF 55,000,000'], correct: 1, explanation: 'Consultancy share = 100% − 45% − 35% = 20%. 220,000,000 × 20% = 44,000,000.' },
    { section: BIM, topic: BIM, stem: 'Why might an institution need to request a supplementary budget partway through the year, rather than relying only on virements?', options: ['Supplementary budgets are never needed', 'When total approved spending needs to increase (not just be reallocated between lines), a virement alone — which keeps the total unchanged — cannot provide that', 'A supplementary budget is simply another name for a virement', 'Only donors can request supplementary budgets'], correct: 1, explanation: 'A virement can only reallocate within the existing approved total; if the institution genuinely needs more total budget authority, that requires a supplementary budget with new appropriation, not a virement.' },
    { section: BIM, topic: BIM, stem: 'What is the purpose of a procurement plan being updated and shared with the finance unit throughout the year?', options: ['It has no bearing on finance operations', 'So the finance unit can anticipate upcoming commitments and payments and plan cash flow accordingly', 'Procurement plans are confidential from finance staff', 'It only needs to be shared once, at the start of the year, with no updates'], correct: 1, explanation: 'Keeping the finance unit updated on the procurement plan lets them anticipate upcoming commitments and payments, which is essential input for accurate cash-flow planning.' },
    { section: BIM, topic: BIM, stem: 'An institution’s quarterly cash ceiling from the treasury is RWF 85,000,000, but approved commitments for the quarter total RWF 93,000,000. What is the most appropriate response?', options: ['Ignore the ceiling and pay all commitments regardless', 'Prioritise payments within the cash ceiling, communicate with the treasury about the gap, and manage or defer lower-priority commitments appropriately', 'Cancel all commitments immediately with no prioritisation', 'Borrow informally from another institution’s budget'], correct: 1, explanation: 'When commitments exceed the cash ceiling released by the treasury, the responsible approach is to prioritise within the available cash, communicate about the shortfall, and manage lower-priority items accordingly — not to simply ignore the ceiling.' },
    { section: BIM, topic: BIM, stem: 'Why does Rwanda’s PFM framework require institutions to report budget execution data into IFMIS regularly, rather than compiling reports manually at year end?', options: ['It has no particular benefit over manual compilation', 'Regular system-based reporting gives near real-time visibility over execution across government, supporting timely oversight and decision-making', 'IFMIS cannot process year-end data at all', 'Manual reporting is always more accurate than system data'], correct: 1, explanation: 'Capturing execution data in IFMIS as transactions happen gives government-wide, near real-time visibility, which supports much more timely oversight than waiting for manually compiled year-end reports.' },
    { section: BIM, topic: BIM, stem: 'A donor-funded component worth RWF 60,000,000 is co-financed with a RWF 15,000,000 government contribution. What percentage of the total co-financed budget does the government contribute?', options: ['15%', '20%', '25%', '30%'], correct: 1, explanation: 'Total = 60,000,000 + 15,000,000 = 75,000,000. Government share = 15,000,000 ÷ 75,000,000 = 0.20, or 20%.' },
    { section: BIM, topic: BIM, stem: 'What is a key reason budget ceilings are communicated to institutions before, not after, they prepare their detailed estimates?', options: ['Ceilings communicated afterwards would be just as useful', 'Institutions need the ceiling in advance to plan realistic, affordable activities within it, rather than planning first and being forced to cut arbitrarily later', 'Ceilings are only relevant to MINECOFIN, not institutions', 'It has no bearing on planning quality'], correct: 1, explanation: 'Knowing the ceiling in advance lets institutions plan activities that are realistically affordable within it; discovering the ceiling only after planning would force arbitrary, late cuts to an already-built plan.' },
    { section: BIM, topic: BIM, stem: 'Why might a finance unit maintain a rolling 3-month cash-flow forecast, updated monthly, in addition to the annual budget?', options: ['It duplicates the annual budget with no added value', 'A short rolling forecast gives a more immediate, accurate picture of near-term cash needs than a static annual plan alone', 'Rolling forecasts are required only for donor-funded institutions', 'It replaces the need for an annual budget entirely'], correct: 1, explanation: 'A rolling short-term forecast, refreshed monthly, captures near-term reality more precisely than a once-a-year annual plan, helping the unit manage imminent cash needs more accurately.' },
    { section: BIM, topic: BIM, stem: 'An institution’s total annual budget rises from RWF 540,000,000 to RWF 615,000,000. What is the percentage increase?', options: ['12%', '13.5%', '14%', '15%'], correct: 2, explanation: 'Increase = 615,000,000 − 540,000,000 = 75,000,000. Percentage increase = 75,000,000 ÷ 540,000,000 ≈ 0.1389, or about 14%.' },
    { section: BIM, topic: BIM, stem: 'What is the main reason “use it or lose it” budgeting behaviour (rushing to spend remaining budget before year end regardless of need) is considered poor practice?', options: ['It is actually good practice and should be encouraged', 'It can lead to wasteful, low-value spending driven by the deadline rather than genuine need, undermining value for money', 'It guarantees a bigger budget the following year', 'It has no effect on audit outcomes'], correct: 1, explanation: '"Use it or lose it" spending is driven by the approaching deadline rather than actual need, which risks wasteful or low-value purchases and undermines sound value-for-money budgeting.' },

    { section: RR, topic: RR, stem: 'A cash book shows RWF 3,450,000. An automated bank transfer of RWF 180,000 for a utility payment has been processed by the bank but not yet entered in the cash book. What is the adjusted cash book balance?', options: ['RWF 3,630,000', 'RWF 3,270,000', 'RWF 3,450,000', 'RWF 180,000'], correct: 1, explanation: 'Adjusted balance = 3,450,000 − 180,000 (automated transfer already processed by the bank) = 3,270,000.' },
    { section: RR, topic: RR, stem: 'Why does a reconciliation need to be re-performed, not just assumed correct, after a prior month’s unexplained difference is finally resolved?', options: ['It does not need to be re-performed', 'To confirm the resolution was applied correctly and the accounts now genuinely agree, rather than simply assuming the issue is closed', 'Re-performing reconciliations is only a formality with no real value', 'Once a difference is found, no further check is ever needed'], correct: 1, explanation: 'Confirming the fix was applied correctly, by re-performing the reconciliation, verifies the accounts genuinely agree now rather than relying on an untested assumption that the issue is resolved.' },
    { section: RR, topic: RR, stem: 'Approved annual budget for a line is RWF 72,000,000; actual expenditure is RWF 64,800,000. What is the variance as a percentage of the approved budget?', options: ['8% underspend', '10% underspend', '12% underspend', '9% underspend'], correct: 1, explanation: 'Variance = 72,000,000 − 64,800,000 = 7,200,000. As a percentage: 7,200,000 ÷ 72,000,000 = 0.10, or 10% underspend.' },
    { section: RR, topic: RR, stem: 'Office furniture costs RWF 3,200,000, has a residual value of RWF 200,000 and a 5-year useful life. What is the annual straight-line depreciation charge?', options: ['RWF 640,000', 'RWF 600,000', 'RWF 700,000', 'RWF 560,000'], correct: 1, explanation: 'Depreciation = (3,200,000 − 200,000) ÷ 5 = 3,000,000 ÷ 5 = 600,000 per year.' },
    { section: RR, topic: RR, stem: 'A budget execution report explains an overspend as caused by an unplanned emergency repair. Why is naming the specific cause more useful than simply noting "costs were higher than planned"?', options: ['There is no real difference between the two statements', 'A specific cause lets management judge whether the overspend was a reasonable one-off response to genuine necessity or a sign of a deeper planning or control problem', 'Specific causes are only needed for amounts over RWF 100,000,000', 'Vague explanations are always preferred to avoid blame'], correct: 1, explanation: 'Naming the actual cause lets management assess whether the variance reflects a justified, one-off response to necessity or points to a more systemic planning or control weakness — a vague statement cannot support that judgement.' },
    { section: RR, topic: RR, stem: 'Why should statutory tax remittance schedules be tracked in a dedicated compliance calendar, separate from general payment processing?', options: ['It serves no real purpose', 'Statutory deadlines carry legal consequences for being missed, so dedicated tracking reduces the risk of accidental late remittance amid routine processing', 'Compliance calendars are only used by private companies', 'Tax remittances have no fixed deadlines'], correct: 1, explanation: 'Because missing a statutory remittance deadline carries legal and financial consequences, tracking these deadlines separately from routine processing reduces the risk they get missed amid everyday workload.' },
    { section: RR, topic: RR, stem: 'Total annual revenue for an institution is RWF 95,000,000, of which RWF 19,000,000 comes from service fees. What percentage of revenue comes from service fees?', options: ['15%', '18%', '20%', '22%'], correct: 2, explanation: '19,000,000 ÷ 95,000,000 = 0.20, or 20%.' },
    { section: RR, topic: RR, stem: 'Why does a qualified audit opinion on a specific balance (for example, inventory) not automatically mean the entire financial statements are unreliable?', options: ['It does mean the entire statements are unreliable', 'A qualification can be limited to a specific, identified matter, leaving the auditor’s view on everything else unaffected', 'Qualified opinions apply to every line item automatically', 'Auditors are not permitted to qualify only part of an opinion'], correct: 1, explanation: 'A qualified opinion is typically limited to the specific matter the auditor identifies (such as one balance or disclosure), rather than casting doubt on every other balance in the financial statements.' },
    { section: RR, topic: RR, stem: 'A reconciling difference of RWF 85,000 is traced to a transposition error (RWF 850,000 recorded as RWF 765,000) in the cash book. What correcting entry is needed in the cash book?', options: ['Reduce the cash book by RWF 85,000', 'Increase the cash book by RWF 85,000', 'Reduce the cash book by RWF 850,000', 'No entry is needed'], correct: 1, explanation: 'The amount was understated by 850,000 − 765,000 = 85,000, so the cash book needs to be increased by RWF 85,000 to correct the error.' },
    { section: RR, topic: RR, stem: 'Why is it useful for a budget execution report to show a trend over several quarters, rather than only the current quarter in isolation?', options: ['Trends are irrelevant to budget execution', 'A trend shows whether a variance is a one-off event or part of a recurring pattern, which affects what response is appropriate', 'Showing multiple quarters is only a formatting convention with no analytical value', 'Only annual figures should ever be shown'], correct: 1, explanation: 'Seeing the trend across several quarters helps distinguish a genuine one-off variance from a recurring pattern, which is important context for deciding what kind of response, if any, is warranted.' },
    { section: RR, topic: RR, stem: 'A grant agreement requires quarterly financial reports to the donor within 30 days of quarter end. The Q2 report was submitted 45 days after quarter end. What is the most likely consequence of this kind of repeated non-compliance?', options: ['No consequence; donors never enforce reporting deadlines', 'Risk to the institution’s relationship with the donor and possibly to continued or future funding, since reporting compliance is usually a condition of the grant', 'The grant period is automatically extended', 'The donor is legally required to increase the grant amount'], correct: 1, explanation: 'Timely reporting is typically a condition attached to grant funding; repeated late reporting risks damaging the donor relationship and can jeopardise continued or future funding.' },
    { section: RR, topic: RR, stem: 'Quarterly utility costs were RWF 2,800,000, RWF 3,100,000, RWF 2,950,000 and RWF 3,350,000 across the year. What was the average quarterly utility cost?', options: ['RWF 3,000,000', 'RWF 3,050,000', 'RWF 3,100,000', 'RWF 2,950,000'], correct: 1, explanation: 'Total = 2,800,000 + 3,100,000 + 2,950,000 + 3,350,000 = 12,200,000. Average = 12,200,000 ÷ 4 = 3,050,000.' },

    { section: PSY, topic: PSY, stem: 'A payment of RWF 2,700,000 is split into 9 equal instalments. After 5 instalments, how much remains?', options: ['RWF 1,200,000', 'RWF 1,500,000', 'RWF 900,000', 'RWF 1,800,000'], correct: 0, explanation: 'Each instalment = 2,700,000 ÷ 9 = 300,000. Five paid = 1,500,000. Remaining = 2,700,000 − 1,500,000 = 1,200,000.' },
    { section: PSY, topic: PSY, stem: 'A unit tested 90 vouchers and found 18 with an issue. What percentage had an issue?', options: ['15%', '18%', '20%', '22%'], correct: 2, explanation: '18 ÷ 90 = 0.20, or 20%.' },
    { section: PSY, topic: PSY, stem: 'An allowance budget of RWF 4,800,000 is cut by 25%. What is the new budget?', options: ['RWF 3,200,000', 'RWF 3,600,000', 'RWF 4,000,000', 'RWF 3,800,000'], correct: 1, explanation: '4,800,000 × (1 − 0.25) = 4,800,000 × 0.75 = 3,600,000.' },
    { section: PSY, topic: PSY, stem: 'Rule: "Every purchase order over RWF 15,000,000 requires two competing quotations." A RWF 15,500,000 purchase order has only one quotation on file. What does this represent?', options: ['A correctly followed process', 'A likely control breach, since the threshold was crossed and the second quotation requirement was not met', 'Acceptable, since the amount is close to the threshold', 'Evidence the threshold should be raised'], correct: 1, explanation: 'Once the PO value crosses the stated threshold, the two-quotation requirement applies; having only one quotation on file for a PO above that threshold is a likely breach.' },
    { section: PSY, topic: PSY, stem: 'A colleague suggests over-estimating next year’s expenditure needs "to be safe," even though realistic planning suggests a lower figure. What is the main risk of this approach?', options: ['There is no risk at all', 'It distorts the credibility of the budget submission and can misallocate scarce government resources away from areas of genuine need', 'It guarantees the institution gets exactly what it asks for', 'It has no bearing on other institutions’ budgets'], correct: 1, explanation: 'Deliberately over-estimating needs distorts the budgeting process and can divert limited government resources away from areas with genuine, better-justified needs elsewhere.' },
    { section: PSY, topic: PSY, stem: 'Total expenditure rose from RWF 410,000,000 to RWF 451,000,000. What is the percentage increase?', options: ['8%', '9%', '10%', '11%'], correct: 2, explanation: 'Increase = 451,000,000 − 410,000,000 = 41,000,000. Percentage increase = 41,000,000 ÷ 410,000,000 = 0.10, or 10%.' },
    { section: PSY, topic: PSY, stem: 'A supervisor instructs a junior accountant to classify a clearly capital item (a new vehicle) as a recurrent expense "to simplify the reporting." What should the junior accountant do?', options: ['Comply, since the supervisor instructed it', 'Decline, explain that the classification is incorrect per accounting policy, and escalate if the instruction persists', 'Comply but keep a private note explaining the real classification', 'Reclassify it the following year with no explanation'], correct: 1, explanation: 'Misclassifying a capital item as recurrent misstates the financial statements; the correct response is to explain the proper classification and escalate if pressed to misclassify anyway.' },
    { section: PSY, topic: PSY, stem: 'A reconciliation shows the cash book overstated by RWF 420,000 due to a casting (addition) error. What correcting entry is needed?', options: ['Increase the cash book by RWF 420,000', 'Reduce the cash book by RWF 420,000', 'No entry is needed, since it is only a minor error', 'Reduce the bank statement balance by RWF 420,000'], correct: 1, explanation: 'Since the cash book figure is overstated by 420,000 due to an addition error, it must be reduced by RWF 420,000 to correct it.' },
    { section: PSY, topic: PSY, stem: 'An institution’s total procurement spend is RWF 180,000,000, of which RWF 27,000,000 was awarded without competitive bidding under an emergency exception. What percentage of total procurement spend was non-competitive?', options: ['10%', '12.5%', '15%', '18%'], correct: 2, explanation: '27,000,000 ÷ 180,000,000 = 0.15, or 15%.' },
    { section: PSY, topic: PSY, stem: 'You discover a figure in a report you already submitted was based on an outdated version of a spreadsheet, though the final conclusion is unaffected. What is the correct response?', options: ['Say nothing since the conclusion is unchanged', 'Notify the recipients, correct the figure, and reissue or annotate the report so the record is accurate', 'Wait to see if anyone notices', 'Simply remember not to make the same mistake next time, with no correction issued'], correct: 1, explanation: 'Even when the bottom-line conclusion is unaffected, a known factual error in a submitted report should be corrected and communicated, so the record held by recipients is accurate.' },
    { section: PSY, topic: PSY, stem: 'A budget ceiling increases from RWF 500,000,000 to RWF 560,000,000. What is the percentage increase?', options: ['10%', '12%', '14%', '16%'], correct: 1, explanation: 'Increase = 560,000,000 − 500,000,000 = 60,000,000. Percentage increase = 60,000,000 ÷ 500,000,000 = 0.12, or 12%.' },
    { section: AS, topic: AS, stem: 'Printer and office equipment total RWF 2,100,000 with a 3-year useful life and no residual value. What is the monthly depreciation charge?', options: ['RWF 700,000', 'RWF 58,333', 'RWF 175,000', 'RWF 70,000'], correct: 1, explanation: 'Annual depreciation = 2,100,000 ÷ 3 = 700,000. Monthly = 700,000 ÷ 12 ≈ 58,333.' },
    { section: BIM, topic: BIM, stem: 'A ministry receives a RWF 36,000,000 cash ceiling for the month, of which RWF 21,000,000 is committed to payroll. What percentage of the ceiling remains for other payments?', options: ['40%', '41.7%', '58.3%', '60%'], correct: 1, explanation: 'Remaining = 36,000,000 − 21,000,000 = 15,000,000. As a percentage of the ceiling: 15,000,000 ÷ 36,000,000 ≈ 0.4167, or about 41.7%.' },

    { section: 'Case study: Musanze District Roads Unit', topic: BIM, caseKey: 'musanze-roads', marks: 2, stem: 'What is the variance on the road grading and gravel line, and what type is it?', options: ['RWF 7,300,000 overspend', 'RWF 7,300,000 underspend', 'RWF 97,300,000 overspend', 'No variance'], correct: 0, explanation: 'Variance = 52,300,000 − 45,000,000 = 7,300,000. Since actual exceeds budget, this is an overspend.' },
    { section: 'Case study: Musanze District Roads Unit', topic: BIM, caseKey: 'musanze-roads', marks: 2, stem: 'What is the variance on the culvert repairs line, and what type is it?', options: ['RWF 6,600,000 overspend', 'RWF 6,600,000 underspend', 'RWF 29,400,000 underspend', 'No variance'], correct: 1, explanation: 'Variance = 18,000,000 − 11,400,000 = 6,600,000. Since actual is below budget, this is an underspend.' },
    { section: 'Case study: Musanze District Roads Unit', topic: BIM, caseKey: 'musanze-roads', marks: 2, stem: 'What is the net (overall) variance across all three lines for the quarter, and what type is it?', options: ['RWF 750,000 overspend overall', 'RWF 750,000 underspend overall', 'RWF 13,900,000 overspend overall', 'No net variance'], correct: 0, explanation: 'Total approved = 45,000,000 + 18,000,000 + 6,000,000 = 69,000,000. Total actual = 52,300,000 + 11,400,000 + 6,050,000 = 69,750,000. Net variance = 69,750,000 − 69,000,000 = 750,000 overspend overall.' },
    { section: 'Case study: Musanze District Roads Unit', topic: BIM, caseKey: 'musanze-roads', marks: 2, stem: 'Why could looking only at the small net variance (RWF 750,000 overspend overall) be misleading about this unit’s budget performance?', options: ['It is not misleading at all', 'It masks a large overspend on one line being offset by a large underspend on another, each of which needs its own explanation', 'It means every line performed exactly to budget', 'Net variances are always more accurate than line-by-line figures'], correct: 1, explanation: 'The small overall net figure hides the fact that one line significantly overspent while another significantly underspent — a budget execution report should explain each line, not just the net position.' },
    { section: 'Case study: Musanze District Roads Unit', topic: BIM, caseKey: 'musanze-roads', marks: 2, stem: 'Given the contractor delay, what is correct to say about the underspent culvert repairs budget?', options: ['It automatically carries over in full to next year with no further process', 'It generally cannot simply roll over; completing the work next year will need a new purchase order and proper budget authorisation', 'It must be returned to the contractor as a penalty', 'It should be spent immediately on an unrelated activity before year end'], correct: 1, explanation: 'Since public budgets are approved annually, continuing the delayed work in the next financial year needs a fresh purchase order and budget authorisation, not an automatic carry-over.' },
    { section: 'Case study: Musanze District Roads Unit', topic: RR, caseKey: 'musanze-roads', marks: 2, stem: 'What is the site supervisor’s net pay after the PAYE and pension deductions shown?', options: ['RWF 380,000', 'RWF 341,600', 'RWF 311,600', 'RWF 349,600'], correct: 2, explanation: 'Net pay = 380,000 − 38,000 (PAYE) − 30,400 (pension contribution) = 311,600.' },
    { section: 'Case study: Musanze District Roads Unit', topic: RR, caseKey: 'musanze-roads', marks: 2, stem: 'Why must both the PAYE and pension deductions be accurately documented and remitted on time?', options: ['They are optional courtesies to staff', 'They are statutory obligations; late or incorrect remittance creates compliance risk and can harm staff’s own benefit entitlements', 'They only matter if the supervisor complains', 'They are recorded only for internal interest, with no external reporting requirement'], correct: 1, explanation: 'Payroll deductions such as PAYE and pension contributions are legally required and also protect employees’ own benefit records, so accuracy and timely remittance matter both for compliance and for staff welfare.' },
    { section: 'Case study: Musanze District Roads Unit', topic: BIM, caseKey: 'musanze-roads', marks: 2, stem: 'What is the most appropriate action regarding the road-grading overspend for the quarterly budget execution report?', options: ['Omit the line to avoid awkward questions', 'Explain the cause (the rise in gravel transport costs) and assess whether an authorised virement or other proper remedy is needed', 'Simply note that costs rose, with no further action', 'Instruct the contractor to absorb the extra cost with no institutional review'], correct: 1, explanation: 'The report should explain what caused the overspend and the accountant should consider whether a formal, authorised remedy — such as a virement from an underspent line, if the rules allow — is appropriate.' },
  ],
};

